// ============================================================
// 1. MOTOR PROCEDURAL DE TEXTURAS (src/engine/textures.js)
// ============================================================
/**
 * Generadores procedurales de texturas para paredes (5x15 -> 64x192 px nativas),
 * cantos (64x192 px) y puertas (64x64 px).
 * Módulo compartido: lo usa el motor (raycaster.js) para renderizar la Demo 3D
 * y el Editor (editor.js) para dibujar las miniaturas del selector de estilos.
 * No depende de RaycasterEngine ni de ninguna instancia: cada función crea su propio
 * canvas y devuelve un Uint32Array de píxeles listo para usar como textura con .width y .height.
 */

function createCanvasCtx(w, h = w) {
  const canvas = (typeof document !== 'undefined')
    ? document.createElement('canvas')
    : { width: w, height: h, getContext: () => null };
  canvas.width = w;
  canvas.height = h;
  return canvas.getContext ? canvas.getContext('2d', { willReadFrequently: true }) : null;
}

function addNoise(ctx, w, h = w, amount = 10) {
  if (!ctx) return;
  const img = ctx.getImageData(0, 0, w, h);
  for (let i = 0; i < img.data.length; i += 4) {
    const noise = (Math.random() - 0.5) * amount;
    img.data[i] = Math.min(255, Math.max(0, img.data[i] + noise));
    img.data[i + 1] = Math.min(255, Math.max(0, img.data[i + 1] + noise));
    img.data[i + 2] = Math.min(255, Math.max(0, img.data[i + 2] + noise));
  }
  ctx.putImageData(img, 0, 0);
}

function toPixels(ctx, w, h = w) {
  if (!ctx) {
    const arr = new Uint32Array(w * h);
    arr.width = w;
    arr.height = h;
    arr.hasTransparency = false;
    return arr;
  }
  const arr = new Uint32Array(ctx.getImageData(0, 0, w, h).data.buffer);
  arr.width = w;
  arr.height = h;
  let hasTrans = false;
  for (let i = 0; i < arr.length; i++) {
    if (((arr[i] >> 24) & 0xFF) < 250) {
      hasTrans = true;
      break;
    }
  }
  arr.hasTransparency = hasTrans;
  return arr;
}

// ============================================================
// PAREDES (Proporción nativa 5:15 -> ancho 64px, alto 192px)
// ============================================================

/** Castillo: muro de piedra/ladrillo dungeon continuo en 192px (12 filas de 16px) */
function createStoneWallPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  ctx.fillStyle = '#484b54';
  ctx.fillRect(0, 0, w, h);

  const brickH = 16;
  const brickW = 32;
  for (let y = 0; y < h; y += brickH) {
    const row = Math.floor(y / brickH);
    const offsetX = (row % 2 === 0) ? 0 : brickW / 2;
    for (let x = -brickW; x < w + brickW; x += brickW) {
      const actualX = x + offsetX;
      const shade = 65 + Math.floor(Math.random() * 20);
      ctx.fillStyle = `rgb(${shade}, ${shade + 2}, ${shade + 8})`;
      ctx.fillRect(actualX + 1, y + 1, brickW - 2, brickH - 2);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.12)';
      ctx.fillRect(actualX + 1, y + 1, brickW - 2, 2);
      ctx.fillRect(actualX + 1, y + 1, 2, brickH - 2);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
      ctx.fillRect(actualX + 1, y + brickH - 2, brickW - 2, 2);
      ctx.fillRect(actualX + brickW - 2, y + 1, 2, brickH - 2);
    }
    ctx.fillStyle = '#26282e';
    ctx.fillRect(0, y, w, 2);
  }
  addNoise(ctx, w, h, 18);
  return toPixels(ctx, w, h);
}

/** Blanca: panel liso con un único gradiente continuo de techo a suelo (sin bandas repetidas) */
function createWhiteWallPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#eef0f3');
  grad.addColorStop(1, '#d9dce1');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);
  addNoise(ctx, w, h, 4);
  return toPixels(ctx, w, h);
}

/** Cristal: panel de vidrio liso y translúcido continuo en toda la altura de la pared */
function createCrystalWallPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // Panel de vidrio translúcido con tinte cian/celeste suave (~32% a ~48% opacidad)
  const grad = ctx.createLinearGradient(0, 0, w, h);
  grad.addColorStop(0, 'rgba(159, 224, 251, 0.32)');
  grad.addColorStop(0.5, 'rgba(74, 168, 221, 0.38)');
  grad.addColorStop(1, 'rgba(28, 95, 143, 0.48)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // Montantes/perfiles verticales laterales del panel de vidrio
  ctx.fillStyle = 'rgba(180, 230, 255, 0.55)';
  ctx.fillRect(0, 0, 2, h);
  ctx.fillRect(w - 2, 0, 2, h);

  // Bisel superior e inferior
  ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
  ctx.fillRect(0, 0, w, 1);
  ctx.fillStyle = 'rgba(28, 95, 143, 0.6)';
  ctx.fillRect(0, h - 2, w, 2);

  // Destello diagonal superior intenso y reflectante
  const glareGrad1 = ctx.createLinearGradient(0, 0, w * 0.4, h * 0.4);
  glareGrad1.addColorStop(0, 'rgba(255, 255, 255, 0.70)');
  glareGrad1.addColorStop(1, 'rgba(255, 255, 255, 0.15)');
  ctx.fillStyle = glareGrad1;
  ctx.beginPath();
  ctx.moveTo(w * 0.08, 0);
  ctx.lineTo(w * 0.42, 0);
  ctx.lineTo(0, h * 0.42);
  ctx.lineTo(0, h * 0.08);
  ctx.closePath();
  ctx.fill();

  // Segundo reflejo diagonal inferior
  const glareGrad2 = ctx.createLinearGradient(0, h * 0.45, w * 0.85, h);
  glareGrad2.addColorStop(0, 'rgba(255, 255, 255, 0.45)');
  glareGrad2.addColorStop(1, 'rgba(255, 255, 255, 0.10)');
  ctx.fillStyle = glareGrad2;
  ctx.beginPath();
  ctx.moveTo(w * 0.50, 0);
  ctx.lineTo(w * 0.85, 0);
  ctx.lineTo(0, h * 0.85);
  ctx.lineTo(0, h * 0.50);
  ctx.closePath();
  ctx.fill();

  return toPixels(ctx, w, h);
}

// ============================================================
// CANTOS / JAMBAS (64x192 px continuos para acompañar a paredes y vanos)
// ============================================================

/** Castillo: marco/jamba metálica continua con remaches (64x192 px) */
function createStoneCapPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  ctx.fillStyle = '#1c1f26';
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = '#2f3542';
  ctx.fillRect(4, 0, 10, h);
  ctx.fillRect(w - 14, 0, 10, h);
  for (let y = 8; y < h; y += 16) {
    ctx.fillStyle = '#4b5366';
    ctx.fillRect(2, y, w - 4, 3);
    ctx.fillStyle = '#8395a7';
    ctx.fillRect(6, y - 1, 3, 3);
    ctx.fillRect(w - 9, y - 1, 3, 3);
  }
  return toPixels(ctx, w, h);
}

/** Blanca: jamba lisa clara continua a juego con la pared blanca (64x192 px) */
function createWhiteCapPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#e6e8ec');
  grad.addColorStop(1, '#cfd2d8');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);
  return toPixels(ctx, w, h);
}

/** Negra: jamba lisa oscura continua a juego con la puerta negra (64x192 px) */
function createBlackCapPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#1c1e24');
  grad.addColorStop(1, '#08090b');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);
  return toPixels(ctx, w, h);
}

/** Cristal: jamba lisa de vidrio translúcido continua (64x192 px) */
function createCrystalCapPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(127, 211, 247, 0.40)');
  grad.addColorStop(1, 'rgba(28, 95, 143, 0.52)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // Perfiles sutiles de borde
  ctx.fillStyle = 'rgba(255, 255, 255, 0.45)';
  ctx.fillRect(0, 0, 2, h);
  ctx.fillRect(w - 2, 0, 2, h);
  return toPixels(ctx, w, h);
}

// ============================================================
// VENTANA (Pared completa 64x192 con dintel, hueco central y antepecho)
// ============================================================

function createWindowPixels(w = 64, h = 192) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // 1. Muro de fondo de piedra en toda la altura
  ctx.fillStyle = '#484b54';
  ctx.fillRect(0, 0, w, h);

  const brickH = 16;
  const brickW = 32;
  for (let y = 0; y < h; y += brickH) {
    const row = Math.floor(y / brickH);
    const offsetX = (row % 2 === 0) ? 0 : brickW / 2;
    for (let x = -brickW; x < w + brickW; x += brickW) {
      const actualX = x + offsetX;
      const shade = 65 + Math.floor(Math.random() * 20);
      ctx.fillStyle = `rgb(${shade}, ${shade + 2}, ${shade + 8})`;
      ctx.fillRect(actualX + 1, y + 1, brickW - 2, brickH - 2);
    }
    ctx.fillStyle = '#26282e';
    ctx.fillRect(0, y, w, 2);
  }

  // Proporciones arquitectónicas del vano:
  // Dintel superior: de 0 a 51px (0 a 0.8m)
  // Hueco de la ventana: de 51px a 141px (0.8m a 2.2m)
  // Antepecho inferior: de 141px a 192px (2.2m a 3.0m)
  const winTop = 51;
  const winBottom = 141;
  const winHeight = winBottom - winTop;

  // Marco de la ventana
  ctx.fillStyle = '#1e222a';
  ctx.fillRect(4, winTop, w - 8, winHeight);
  ctx.fillStyle = '#2f3640';
  ctx.fillRect(8, winTop + 4, w - 16, winHeight - 8);

  // Cristal de la ventana
  const grad = ctx.createLinearGradient(0, winTop, w, winBottom);
  grad.addColorStop(0, '#54a0ff');
  grad.addColorStop(0.35, '#70a1ff');
  grad.addColorStop(0.7, '#2e86de');
  grad.addColorStop(1, '#1e3799');
  ctx.fillStyle = grad;
  ctx.fillRect(11, winTop + 7, w - 22, winHeight - 14);

  // Destellos de cristal
  ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
  ctx.beginPath();
  ctx.moveTo(16, winTop + 7);
  ctx.lineTo(28, winTop + 7);
  ctx.lineTo(11, winTop + 24);
  ctx.lineTo(11, winTop + 12);
  ctx.closePath();
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(34, winTop + 7);
  ctx.lineTo(44, winTop + 7);
  ctx.lineTo(11, winTop + 40);
  ctx.lineTo(11, winTop + 30);
  ctx.closePath();
  ctx.fill();

  // Parteluz y travesaño de hierro
  const midX = Math.floor(w / 2);
  const midY = Math.floor((winTop + winBottom) / 2);
  ctx.fillStyle = '#151922';
  ctx.fillRect(midX - 2, winTop + 6, 4, winHeight - 12);
  ctx.fillRect(10, midY - 2, w - 20, 4);

  ctx.fillStyle = '#8395a7';
  ctx.fillRect(midX - 1, midY - 1, 2, 2);

  addNoise(ctx, w, h, 10);
  return toPixels(ctx, w, h);
}

// ============================================================
// PUERTAS (Proporción nativa 5:10 -> ancho 64px, alto 128px)
// Idénticas a sus paredes, sin marcos y con solo el picaporte (sin círculo de orientación)
// ============================================================

/** Castillo: puerta de madera maciza en tablones verticales con herrajes de forja y tirador medieval (64x128 px) */
function createWoodDoorPixels(w = 64, h = 128) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // 1. 4 Tablones verticales de roble / castaño con variación de tono
  const plankColors = ['#734929', '#7e512e', '#6b4325', '#774c2b'];
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = plankColors[i];
    ctx.fillRect(i * 16, 0, 16, h);
  }

  // 2. Vetas de madera verticales y textura orgánica
  addNoise(ctx, w, h, 14);

  // 3. Ranuras oscuras entre tablones con bisel de luz
  for (const gx of [15, 31, 47]) {
    ctx.fillStyle = '#201209';
    ctx.fillRect(gx, 0, 1, h);
    ctx.fillStyle = 'rgba(255, 200, 150, 0.18)';
    ctx.fillRect(gx + 1, 0, 1, h);
  }

  // 4. Sombra perimetral para encajar en el marco
  ctx.fillStyle = 'rgba(32, 18, 9, 0.6)';
  ctx.fillRect(0, 0, w, 2);
  ctx.fillRect(0, h - 2, w, 2);
  ctx.fillRect(0, 0, 2, h);
  ctx.fillRect(w - 2, 0, 2, h);

  // 5. Herrajes de forja oscura (pletinas horizontales de refuerzo con remaches)
  for (const strapY of [18, 98]) {
    // Sombra proyectada
    ctx.fillStyle = 'rgba(25, 15, 8, 0.55)';
    ctx.fillRect(2, strapY + 8, w - 4, 2);

    // Cuerpo de forja
    ctx.fillStyle = '#24282e';
    ctx.fillRect(2, strapY, w - 4, 8);

    // Bisel superior claro
    ctx.fillStyle = '#4b5360';
    ctx.fillRect(2, strapY, w - 4, 1);

    // Bisel inferior oscuro
    ctx.fillStyle = '#101216';
    ctx.fillRect(2, strapY + 7, w - 4, 1);

    // Remaches de forja en cada tablón
    for (const rx of [8, 24, 40, 56]) {
      ctx.fillStyle = '#8c96aa';
      ctx.fillRect(rx, strapY + 2, 2, 1);
      ctx.fillStyle = '#24282e';
      ctx.fillRect(rx, strapY + 3, 2, 1);
      ctx.fillStyle = '#0a0b0e';
      ctx.fillRect(rx, strapY + 4, 2, 1);
    }
  }

  // 6. Placa y picaporte de latón/dorado medieval
  // Placa posterior
  ctx.fillStyle = '#785a14';
  ctx.fillRect(45, 55, 11, 23);
  ctx.fillStyle = '#cfac38';
  ctx.fillRect(46, 56, 9, 21);
  ctx.fillStyle = '#ffe066';
  ctx.fillRect(46, 56, 9, 1);
  ctx.fillRect(46, 56, 1, 21);
  ctx.fillStyle = '#5a420e';
  ctx.fillRect(46, 76, 9, 1);
  ctx.fillRect(54, 56, 1, 21);

  // Ojo de la cerradura
  ctx.fillStyle = '#0f0a05';
  ctx.fillRect(50, 68, 2, 4);
  ctx.fillRect(49, 70, 4, 1);

  // Manilla dorada horizontal
  ctx.fillStyle = 'rgba(30, 20, 8, 0.4)';
  ctx.fillRect(37, 65, 14, 2);
  ctx.fillStyle = '#ffea80';
  ctx.fillRect(38, 62, 13, 1);
  ctx.fillStyle = '#d4af37';
  ctx.fillRect(38, 63, 13, 2);
  ctx.fillStyle = '#785a14';
  ctx.fillRect(38, 65, 13, 1);

  return toPixels(ctx, w, h);
}

/** Blanca: puerta blanca de oficina moderna con cuarterones moldeados en relieve 3D y manilla de acero inox (64x128 px) */
function createWhiteDoorPixels(w = 64, h = 128) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // Fondo sutil blanco oficina con degradado
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#f5f6f8');
  grad.addColorStop(1, '#e3e6ec');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);
  addNoise(ctx, w, h, 3);

  // Sombra de borde perimetral
  ctx.fillStyle = 'rgba(175, 180, 190, 0.5)';
  ctx.fillRect(0, 0, w, 1);
  ctx.fillRect(0, h - 1, w, 1);
  ctx.fillRect(0, 0, 1, h);
  ctx.fillRect(w - 1, 0, 1, h);

  // 2 Cuarterones moldeados con biseles 3D
  const panels = [
    { x: 8, y: 10, w: 48, h: 45 },
    { x: 8, y: 68, w: 48, h: 50 }
  ];

  for (const p of panels) {
    // Ranura exterior sombreada (hueco rehundido)
    ctx.fillStyle = '#969ca8';
    ctx.fillRect(p.x, p.y, p.w, 1);
    ctx.fillRect(p.x, p.y, 1, p.h);
    ctx.fillStyle = '#b8bec8';
    ctx.fillRect(p.x + 1, p.y + 1, p.w - 2, 1);
    ctx.fillRect(p.x + 1, p.y + 1, 1, p.h - 2);

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(p.x, p.y + p.h - 1, p.w, 1);
    ctx.fillRect(p.x + p.w - 1, p.y, 1, p.h);

    // Centro abombado / relieve interior
    const ix = p.x + 4, iy = p.y + 4, iw = p.w - 8, ih = p.h - 8;
    ctx.fillStyle = '#e4e8ee';
    ctx.fillRect(ix, iy, iw, ih);

    // Bisel de relieve centro
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(ix, iy, iw, 1);
    ctx.fillRect(ix, iy, 1, ih);
    ctx.fillStyle = '#b8bec8';
    ctx.fillRect(ix, iy + ih - 1, iw, 1);
    ctx.fillRect(ix + iw - 1, iy, 1, ih);
  }

  // Manilla moderna de acero inoxidable cepillado
  // Roseta
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(48, 58, 6, 9);
  ctx.fillStyle = '#aab0bc';
  ctx.fillRect(49, 59, 4, 7);
  ctx.fillStyle = '#5a5f69';
  ctx.fillRect(48, 66, 6, 1);
  ctx.fillRect(53, 58, 1, 9);

  // Manilla palanca horizontal
  ctx.fillStyle = 'rgba(80, 85, 95, 0.35)';
  ctx.fillRect(37, 64, 14, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(38, 61, 13, 1);
  ctx.fillStyle = '#cfd4de';
  ctx.fillRect(38, 62, 13, 1);
  ctx.fillStyle = '#5a5f69';
  ctx.fillRect(38, 63, 13, 1);

  return toPixels(ctx, w, h);
}

/** Negra: puerta ejecutiva de grafito mate oscuro con incrustaciones metálicas horizontales y manilla cromada (64x128 px) */
function createBlackDoorPixels(w = 64, h = 128) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // Fondo grafito mate oscuro
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, '#1a1b20');
  grad.addColorStop(1, '#0e0f13');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);
  addNoise(ctx, w, h, 4);

  // 4 Tiras metálicas horizontales de aluminio cepillado (inlays modernos)
  for (const sy of [22, 46, 82, 106]) {
    ctx.fillStyle = '#0a0b0e';
    ctx.fillRect(4, sy - 1, w - 8, 1);
    ctx.fillStyle = '#e8ecf4';
    ctx.fillRect(4, sy, w - 8, 1);
    ctx.fillStyle = '#9aa1af';
    ctx.fillRect(4, sy + 1, w - 8, 1);
    ctx.fillStyle = '#32363e';
    ctx.fillRect(4, sy + 2, w - 8, 1);
  }

  // Bisel de borde perimetral sutil
  ctx.fillStyle = '#2c2f38';
  ctx.fillRect(0, 0, w, 1);
  ctx.fillRect(0, 0, 1, h);
  ctx.fillStyle = '#08090b';
  ctx.fillRect(0, h - 1, w, 1);
  ctx.fillRect(w - 1, 0, 1, h);

  // Manilla contemporánea de cromo / acero satinado
  ctx.fillStyle = '#e8ecf4';
  ctx.fillRect(48, 58, 6, 9);
  ctx.fillStyle = '#9aa1af';
  ctx.fillRect(49, 59, 4, 7);
  ctx.fillStyle = '#14161a';
  ctx.fillRect(48, 66, 6, 1);
  ctx.fillRect(53, 58, 1, 9);

  // Palanca horizontal
  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
  ctx.fillRect(37, 64, 14, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(38, 61, 13, 1);
  ctx.fillStyle = '#c5ccd8';
  ctx.fillRect(38, 62, 13, 1);
  ctx.fillStyle = '#32363e';
  ctx.fillRect(38, 63, 13, 1);

  return toPixels(ctx, w, h);
}

/** Cristal: exactamente como la pared de cristal pero con picaporte, sin marco ni nada (64x128 px) */
function createCrystalDoorPixels(w = 64, h = 128) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);

  // Panel de vidrio translúcido idéntico a la pared de cristal de borde a borde (sin marco)
  const grad = ctx.createLinearGradient(0, 0, w, h);
  grad.addColorStop(0, 'rgba(159, 224, 251, 0.32)');
  grad.addColorStop(0.5, 'rgba(74, 168, 221, 0.38)');
  grad.addColorStop(1, 'rgba(28, 95, 143, 0.48)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // Destello diagonal reflectante continuo idéntico a la pared
  const glareGrad = ctx.createLinearGradient(0, 0, w * 0.42, h * 0.42);
  glareGrad.addColorStop(0, 'rgba(255, 255, 255, 0.70)');
  glareGrad.addColorStop(1, 'rgba(255, 255, 255, 0.15)');
  ctx.fillStyle = glareGrad;
  ctx.beginPath();
  ctx.moveTo(w * 0.08, 0);
  ctx.lineTo(w * 0.42, 0);
  ctx.lineTo(0, h * 0.42);
  ctx.lineTo(0, h * 0.08);
  ctx.closePath();
  ctx.fill();

  // Picaporte sólido plateado a media altura
  const handleY = Math.floor(h / 2);
  ctx.fillStyle = '#f0f8ff';
  ctx.beginPath();
  ctx.arc(w - 14, handleY, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#112233';
  ctx.fillRect(w - 15, handleY + 1, 2, 4);

  return toPixels(ctx, w, h);
}

// ============================================================
// REGISTRO DE ESTILOS DISPONIBLES & TEXTURAS PERSONALIZADAS
// ============================================================

/**
 * Convierte un Data URL o Image en un Uint32Array con width y height
 */
function dataUrlToPixels(dataUrl, targetW = 64, targetH = 192, onLoadedCallback = null, fallbackFn = null) {
  if (typeof document === 'undefined') {
    const arr = new Uint32Array(targetW * targetH);
    arr.width = targetW;
    arr.height = targetH;
    arr.hasTransparency = false;
    return arr;
  }
  const canvas = document.createElement('canvas');
  canvas.width = targetW;
  canvas.height = targetH;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  
  if (!dataUrl) {
    if (typeof fallbackFn === 'function') return fallbackFn();
    ctx.fillStyle = '#4a5568';
    ctx.fillRect(0, 0, targetW, targetH);
    return toPixels(ctx, targetW, targetH);
  }

  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => {
    ctx.clearRect(0, 0, targetW, targetH);
    ctx.drawImage(img, 0, 0, targetW, targetH);
    const pixels = toPixels(ctx, targetW, targetH);
    if (typeof onLoadedCallback === 'function') {
      onLoadedCallback(pixels);
    }
  };
  img.onerror = () => {
    if (typeof fallbackFn === 'function') {
      const fb = fallbackFn();
      if (typeof onLoadedCallback === 'function') {
        onLoadedCallback(fb);
      }
    }
  };
  img.src = dataUrl;
  if (img.complete && img.naturalWidth > 0) {
    ctx.drawImage(img, 0, 0, targetW, targetH);
    return toPixels(ctx, targetW, targetH);
  }
  
  if (typeof fallbackFn === 'function') {
    return fallbackFn();
  }
  // Retorno síncrono si la imagen aún no cargó completamente
  ctx.fillStyle = '#3b4252';
  ctx.fillRect(0, 0, targetW, targetH);
  return toPixels(ctx, targetW, targetH);
}

/**
 * Genera automáticamente un canto/jamba coherente (64x192) a partir de una textura de pared
 */
function createCapFromWallImage(wallDataUrl, w = 64, h = 192) {
  if (typeof document === 'undefined') return toPixels(null, w, h);
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });

  if (wallDataUrl) {
    const img = new Image();
    img.src = wallDataUrl;
    if (img.complete && img.naturalWidth > 0) {
      // Dibujar la pared oscurecida
      ctx.drawImage(img, 0, 0, w, h);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
      ctx.fillRect(0, 0, w, h);
    } else {
      ctx.fillStyle = '#2d3748';
      ctx.fillRect(0, 0, w, h);
    }
  } else {
    ctx.fillStyle = '#2d3748';
    ctx.fillRect(0, 0, w, h);
  }

  // Marco/jamba estructurada en los laterales
  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
  ctx.fillRect(0, 0, 8, h);
  ctx.fillRect(w - 8, 0, 8, h);

  // Remaches / perfiles cada 16px
  for (let y = 8; y < h; y += 16) {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';
    ctx.fillRect(3, y, 4, 3);
    ctx.fillRect(w - 7, y, 4, 3);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.fillRect(2, y + 3, 6, 1);
    ctx.fillRect(w - 8, y + 3, 6, 1);
  }

  return toPixels(ctx, w, h);
}

// ============================================================
// TECHOS (textura cuadrada 64×64 px para floor-casting)
// ============================================================

/** Techo blanco: losa lisa con juntas sutiles */
function createWhiteCeilingPixels(w = 64, h = 64) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);
  ctx.fillStyle = '#e8eaed';
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(0,0,0,0.10)';
  ctx.lineWidth = 1;
  for (let x = 0; x <= w; x += 32) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
  for (let y = 0; y <= h; y += 32) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
  addNoise(ctx, w, h, 5);
  return toPixels(ctx, w, h);
}

/** Techo piedra: mismas losas que la pared castillo pero en plano */
function createStoneCeilingPixels(w = 64, h = 64) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);
  ctx.fillStyle = '#484b54';
  ctx.fillRect(0, 0, w, h);
  const brickW = 32, brickH = 16;
  for (let row = 0; row < Math.ceil(h / brickH); row++) {
    const oy = row * brickH;
    const ox = (row % 2 === 0) ? 0 : brickW / 2;
    for (let col = -1; col < Math.ceil(w / brickW) + 1; col++) {
      const bx = col * brickW + ox;
      const shade = 65 + Math.floor(Math.random() * 18);
      ctx.fillStyle = `rgb(${shade},${shade+2},${shade+8})`;
      ctx.fillRect(bx + 1, oy + 1, brickW - 2, brickH - 2);
    }
    ctx.fillStyle = '#26282e';
    ctx.fillRect(0, oy, w, 1);
  }
  addNoise(ctx, w, h, 18);
  return toPixels(ctx, w, h);
}

function createLightCeilingPixels(w = 64, h = 64) {
  const ctx = createCanvasCtx(w, h);
  if (!ctx) return toPixels(null, w, h);
  // Base blanca con ligero tono cálido
  ctx.fillStyle = '#e8e4d8';
  ctx.fillRect(0, 0, w, h);
  // Halo de luz central
  const cx = w / 2, cy = h / 2;
  if (typeof ctx.createRadialGradient === 'function') {
    const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, w * 0.48);
    grad.addColorStop(0, 'rgba(255, 250, 200, 1)');
    grad.addColorStop(0.35, 'rgba(255, 245, 180, 0.7)');
    grad.addColorStop(1, 'rgba(200, 195, 170, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }
  // Carcasa de la lámpara (rectángulo central)
  const lw = w * 0.38, lh = h * 0.22;
  const lx = cx - lw / 2, ly = cy - lh / 2;
  ctx.fillStyle = '#c8c0a0';
  ctx.fillRect(lx, ly, lw, lh);
  ctx.strokeStyle = '#a09070';
  ctx.lineWidth = 1.5;
  if (typeof ctx.strokeRect === 'function') ctx.strokeRect(lx, ly, lw, lh);
  // Cristal interior brillante
  ctx.fillStyle = 'rgba(255, 255, 210, 0.95)';
  ctx.fillRect(lx + 3, ly + 3, lw - 6, lh - 6);
  // Cable fino hacia el techo
  ctx.strokeStyle = '#888070';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx, 0);
  ctx.lineTo(cx, ly);
  ctx.stroke();
  addNoise(ctx, w, h, 8);
  return toPixels(ctx, w, h);
}

const WALL_STYLES = {};
const DOOR_STYLES = {};
const CEILING_STYLES = {};

// Mapeo de generadores procedurales de respaldo (para visualización offline o generadores matemáticos)
const PROCEDURAL_GENERATORS = {
  walls: {
    castle: { wall: createStoneWallPixels, cap: createStoneCapPixels },
    white: { wall: createWhiteWallPixels, cap: createWhiteCapPixels },
    black: { wall: createBlackCapPixels, cap: createBlackCapPixels },
    crystal: { wall: createCrystalWallPixels, cap: createCrystalCapPixels },
    castillo: { wall: createStoneWallPixels, cap: createStoneCapPixels },
    blanca: { wall: createWhiteWallPixels, cap: createWhiteCapPixels },
    negra: { wall: createBlackCapPixels, cap: createBlackCapPixels },
    cristal: { wall: createCrystalWallPixels, cap: createCrystalCapPixels }
  },
  doors: {
    castle: { door: createWoodDoorPixels, cap: createStoneCapPixels },
    white: { door: createWhiteDoorPixels, cap: createWhiteCapPixels },
    black: { door: createBlackDoorPixels, cap: createBlackCapPixels },
    crystal: { door: createCrystalDoorPixels, cap: createCrystalCapPixels },
    castillo: { door: createWoodDoorPixels, cap: createStoneCapPixels },
    blanca: { door: createWhiteDoorPixels, cap: createWhiteCapPixels },
    negra: { door: createBlackDoorPixels, cap: createBlackCapPixels },
    cristal: { door: createCrystalDoorPixels, cap: createCrystalCapPixels }
  },
  ceilings: {
    white: { ceiling: createWhiteCeilingPixels },
    castle: { ceiling: createStoneCeilingPixels },
    light: { ceiling: createLightCeilingPixels },
    blanca: { ceiling: createWhiteCeilingPixels },
    castillo: { ceiling: createStoneCeilingPixels },
    luz: { ceiling: createLightCeilingPixels }
  }
};

// Inicializar estilos de techo procedurales por defecto
CEILING_STYLES['white'] = { label: 'White', pixels: createWhiteCeilingPixels(), gen: createWhiteCeilingPixels };
CEILING_STYLES['castle'] = { label: 'Castle', pixels: createStoneCeilingPixels(), gen: createStoneCeilingPixels };
CEILING_STYLES['light'] = { label: 'With Light', pixels: createLightCeilingPixels(), gen: createLightCeilingPixels };
CEILING_STYLES['blanca'] = CEILING_STYLES['white'];
CEILING_STYLES['castillo'] = CEILING_STYLES['castle'];
CEILING_STYLES['luz'] = CEILING_STYLES['light'];

/**
 * Carga e inicializa WALL_STYLES y DOOR_STYLES a partir de un objeto manifest (e.g. textures.json)
 */
function loadStylesFromManifest(manifest) {
  if (!manifest) return;
  const isStandalone = typeof window !== 'undefined' && !!window.STANDALONE_PROJECT;
  const defaultBaseDir = isStandalone ? 'assets/textures/' : 'assets/textures/';
  const baseDir = manifest.baseDir || defaultBaseDir;

  if (manifest.walls) {
    Object.entries(manifest.walls).forEach(([key, item]) => {
      const proc = PROCEDURAL_GENERATORS.walls[key] || {};
      const isTrans = (item.hasTransparency !== undefined)
        ? item.hasTransparency
        : (/^(crystal|cristal|glass|trans|reja|enrejado)/i.test(key));
      const capFile = item.capFile || ('caps/' + key + '.png');
      WALL_STYLES[key] = {
        label: item.label || key,
        file: item.file,
        pngUrl: item.file ? (baseDir + item.file) : null,
        capFile: capFile,
        capPngUrl: baseDir + capFile,
        wall: proc.wall || createStoneWallPixels,
        cap: proc.cap || createStoneCapPixels,
        hasTransparency: isTrans,
        isCustom: false
      };
    });
  }

  if (manifest.doors) {
    Object.entries(manifest.doors).forEach(([key, item]) => {
      const proc = PROCEDURAL_GENERATORS.doors[key] || {};
      const isTrans = (item.hasTransparency !== undefined)
        ? item.hasTransparency
        : (/^(crystal|cristal|glass|trans|reja|enrejado)/i.test(key));
      const capFile = item.capFile || ('caps/' + key + '.png');
      DOOR_STYLES[key] = {
        label: item.label || key,
        file: item.file,
        pngUrl: item.file ? (baseDir + item.file) : null,
        capFile: capFile,
        capPngUrl: baseDir + capFile,
        door: proc.door || createWoodDoorPixels,
        cap: proc.cap || createStoneCapPixels,
        hasTransparency: isTrans,
        isCustom: false
      };
    });
  }
}

